/* Scola ağaçkakanı: tek kaynaklı çizim + hareketler. Süs amaçlıdır; XP, seviye ya da doğrulama anlamı taşımaz. */
(function(root){
const ART=`<g class="m-all" stroke="#23202f" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"><g class="m-tail"><path d="M84 288L44 326L90 316L102 336L124 292Z" fill="#2b2b3b"/></g><g class="m-legs" fill="none"><path d="M120 296V324M120 324H94M160 296V324M160 324H186" stroke="#23202f" stroke-width="13"/><path d="M120 296V324M120 324H94M160 296V324M160 324H186" stroke="#f2a93b" stroke-width="6"/></g><g class="m-body"><ellipse cx="138" cy="235" rx="68" ry="72" fill="#3a3a4f"/><ellipse cx="156" cy="246" rx="42" ry="55" fill="#fbefd2" stroke="none"/><g class="m-wing"><path d="M104 190C66 202 54 250 70 292C104 282 126 250 124 206Z" fill="#2b2b3b"/><path d="M72 258q10 10 22 0M76 276q10 8 20-2" fill="none" stroke="#fbefd2" stroke-width="4"/></g></g><g class="m-head"><circle cx="150" cy="96" r="72" fill="#3a3a4f"/><ellipse cx="160" cy="108" rx="52" ry="46" fill="#fff" stroke="none"/><g class="m-crest"><path d="M104 58L54 38L96 38L66 10L112 26L112 -6L138 22L156 -8L164 30L170 62Z" fill="#e23b3b"/></g><ellipse cx="124" cy="128" rx="11" ry="7" fill="#ff9fa8" stroke="none"/><ellipse cx="192" cy="130" rx="9" ry="6" fill="#ff9fa8" stroke="none"/><g class="m-eye"><circle cx="136" cy="98" r="18" fill="#fff" stroke-width="3.5"/><circle class="m-pupil" cx="140" cy="99" r="10" fill="#23202f" stroke="none"/><circle cx="144" cy="94" r="3.6" fill="#fff" stroke="none"/><circle cx="180" cy="98" r="18" fill="#fff" stroke-width="3.5"/><circle class="m-pupil" cx="184" cy="99" r="10" fill="#23202f" stroke="none"/><circle cx="188" cy="94" r="3.6" fill="#fff" stroke="none"/></g><path d="M200 106L276 120L200 144Z" fill="#6a6a80"/><path d="M204 124L262 121" fill="none" stroke-width="3" opacity=".6"/></g></g>`;
const VIEW={full:'0 -30 300 375',head:'40 -30 230 205'};
function art(kind,extra){return `<svg class="mascot ${kind==='full'?'':'mascot-head'} ${extra||''}" viewBox="${VIEW[kind]||VIEW.full}" role="img" aria-label="Scola ağaçkakanı" focusable="false">${ART}</svg>`}
if(typeof module==='object'&&module.exports){module.exports={art,ART,VIEW};return}
const calm=()=>root.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
const MOODS={peck:900*3/1000*1000,flap:1000,hop:700,tilt:1500,cheer:1500};
let nodes=[];
function play(el,mood){if(!el||calm())return;Object.keys(MOODS).forEach(m=>el.classList.remove('is-'+m));void el.getBoundingClientRect();el.classList.add('is-'+mood);clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove('is-'+mood),MOODS[mood]+80)}
function all(mood){nodes=nodes.filter(n=>n.isConnected);nodes.forEach(n=>play(n,mood))}
function scan(scope){(scope||document).querySelectorAll('[data-mascot]:not([data-m-ready])').forEach(h=>{const kind=h.dataset.mascot==='full'?'full':'head';h.dataset.mReady='1';h.innerHTML=art(kind);const svg=h.firstElementChild;nodes.push(svg);if(kind==='full')svg.addEventListener('click',()=>play(svg,'peck'));h.addEventListener('pointerenter',()=>play(svg,kind==='full'?'tilt':'peck'))})}
function look(x,y){nodes=nodes.filter(n=>n.isConnected);nodes.forEach(n=>{const ps=n.querySelectorAll('.m-pupil');if(!ps.length)return;const r=n.getBoundingClientRect();if(!r.width)return;const k=n.viewBox.baseVal.width/r.width,dx=(x-(r.left+r.width*.55))*k,dy=(y-(r.top+r.height*.3))*k,d=Math.hypot(dx,dy)||1,m=Math.min(3.4,d/40);ps.forEach(p=>p.style.transform=`translate(${(dx/d*m).toFixed(2)}px,${(dy/d*m).toFixed(2)}px)`)})}
let idleT;function idle(){clearTimeout(idleT);idleT=setTimeout(()=>{const vis=nodes.filter(n=>n.isConnected&&n.classList.contains('mascot')&&!n.classList.contains('mascot-head')&&n.getBoundingClientRect().height);if(vis.length&&!document.hidden)play(vis[0],['peck','tilt','flap','hop'][Math.floor(Math.random()*4)]);idle()},4500+Math.random()*3500)}
document.addEventListener('pointermove',e=>look(e.clientX,e.clientY),{passive:true});
document.addEventListener('DOMContentLoaded',()=>{scan();idle()});
root.Mascot={art,scan,play:all,cheer:()=>all('cheer'),peck:()=>all('peck')};
})(typeof window!=='undefined'?window:globalThis);
